import { useParams, Link } from "react-router-dom";
import { useState, useEffect } from "react";
import Card from "../components/Card";

export default function RoadmapPage() {
  const { name } = useParams();

  const [domain, setDomain] = useState("");
  const [journeyStarted, setJourneyStarted] = useState(false);
  const [learningStarted, setLearningStarted] = useState(false);
  const [currentDay, setCurrentDay] = useState(1);
  const [completedTasks, setCompletedTasks] = useState({});

  const timeline = sessionStorage.getItem("timeline") || "3 months";

  // ✅ LOAD SESSION DATA
  useEffect(() => {
    const newDomain = name?.toLowerCase();

    sessionStorage.setItem("selectedDomain", newDomain);
    setDomain(newDomain);

    setJourneyStarted(sessionStorage.getItem("journeyStarted") === "true");
    setLearningStarted(sessionStorage.getItem("learningStarted") === "true");
    setCurrentDay(parseInt(sessionStorage.getItem("currentDay") || "1"));

    const saved = JSON.parse(sessionStorage.getItem("completedTasks") || "{}");
    setCompletedTasks(saved);
  }, [name]);

  // 🔥 ALL DOMAINS
  const topicMap = {
    "web-development": [
      ["HTML"], ["CSS"], ["Flexbox"], ["JavaScript"], ["DOM"],
      ["React"], ["API"], ["Node.js"], ["MongoDB"], ["Project"]
    ],
    "ai-and-ml": [
      ["Python"], ["NumPy"], ["Pandas"], ["Visualization"],
      ["ML Basics"], ["Regression"], ["Deep Learning"], ["Project"]
    ],
    "cloud-and-devops": [
      ["Linux"], ["Networking"], ["Git"], ["Docker"], ["CI/CD"],
      ["AWS"], ["Kubernetes"], ["Monitoring"], ["Security"], ["Project"]
    ],
    "cybersecurity": [
      ["Networking"], ["Cryptography"], ["Linux Security"], ["Web Security"],
      ["OWASP"], ["Ethical Hacking"], ["Tools"], ["Incident Response"], ["Project"]
    ]
  };

  const topics = topicMap[domain] || [["Basics"]];

  // 🚀 DYNAMIC PLAN BASED ON TIMELINE
  const generatePlan = () => {
    const flatTopics = topics.flat();

    let totalDays = 90;
    if (timeline.includes("month")) totalDays = parseInt(timeline) * 30;
    else if (timeline.includes("year")) totalDays = parseInt(timeline) * 365;

    const totalTopics = flatTopics.length;

    const topicsPerDay = Math.max(1, Math.ceil(totalTopics / totalDays));

    const plan = [];
    let index = 0;

    for (let day = 1; day <= totalDays; day++) {
      const daily = [];

      for (let i = 0; i < topicsPerDay; i++) {
        if (index < totalTopics) {
          daily.push(flatTopics[index]);
          index++;
        }
      }

      if (daily.length === 0) break;

      plan.push(daily);
    }

    return plan;
  };

  // ✅ GENERATE / UPDATE PLAN
  useEffect(() => {
    if (domain) {
      const plan = generatePlan();
      sessionStorage.setItem("roadmapPlan", JSON.stringify(plan));
    }
  }, [domain, timeline]);

  const roadmapPlan = JSON.parse(
    sessionStorage.getItem("roadmapPlan") || "[]"
  );

  const getTasksForDay = (day) => roadmapPlan[day - 1] || [];

  // ✅ PROGRESS
  const totalTasks = roadmapPlan.flat().length;
  const completedCount = Object.values(completedTasks).flat().length;

  const progress = totalTasks
    ? (completedCount / totalTasks) * 100
    : 0;

  // ✅ AUTO NEXT DAY
  useEffect(() => {
    const todayTasks = roadmapPlan[currentDay - 1] || [];
    const completedToday = completedTasks[currentDay] || [];

    const allDone =
      todayTasks.length > 0 &&
      todayTasks.every(task => completedToday.includes(task));

    if (allDone) {
      const nextDay = currentDay + 1;
      setCurrentDay(nextDay);
      sessionStorage.setItem("currentDay", nextDay.toString());
    }
  }, [completedTasks, roadmapPlan]);

  // ✅ START BUTTONS
  const handleStartJourney = () => {
    sessionStorage.setItem("journeyStarted", "true");
    setJourneyStarted(true);
  };

  const handleStartToday = () => {
    sessionStorage.setItem("learningStarted", "true");
    setLearningStarted(true);
  };

  return (
    <div className="space-y-8 text-white">
      <Card title="Learning Roadmap">

        {/* HEADER */}
        <h2 className="text-xl font-bold capitalize">
          🚀 {domain?.replaceAll("-", " ")} Roadmap
        </h2>

        {/* START */}
        {!journeyStarted && (
          <div className="text-center mt-6">
            <button
              onClick={handleStartJourney}
              className="px-6 py-3 bg-green-500 rounded-xl"
            >
              Start Journey
            </button>
          </div>
        )}

        {/* START TODAY */}
        {journeyStarted && !learningStarted && (
          <div className="text-center mt-6">
            <button
              onClick={handleStartToday}
              className="px-6 py-3 bg-blue-500 rounded-xl"
            >
              Start Today
            </button>
          </div>
        )}

        {/* MAIN */}
        {learningStarted && (
          <>
            {/* PROGRESS BAR */}
            <div className="mt-4">
              <div className="w-full bg-slate-700 h-3 rounded-full">
                <div
                  className="h-3 rounded-full"
                  style={{
                    width: `${progress}%`,
                    background: "linear-gradient(90deg, #22c55e, #4f46e5)",
                  }}
                />
              </div>
              <p className="text-gray-400 mt-2">
                {Math.floor(progress)}% completed
              </p>
            </div>

            {/* DAY */}
            <h3 className="mt-4">
              Day {currentDay} / {Math.max(roadmapPlan.length, 1)}
            </h3>

            {/* TASKS */}
            <div className="grid gap-3 mt-4">
              {getTasksForDay(currentDay).map((task, i) => {
                const isDone = completedTasks[currentDay]?.includes(task);

                return (
                  <div
                    key={i}
                    className={`p-4 rounded-xl border ${
                      isDone
                        ? "bg-green-900 border-green-500"
                        : "bg-slate-800 border-slate-700"
                    }`}
                  >
                    {isDone ? "✅" : "⬜"} {task}
                  </div>
                );
              })}
            </div>

            {/* NAV */}
            <Link to="/tasks">
              <button className="mt-6 px-6 py-3 bg-teal-500 rounded-xl">
                Go to Tasks →
              </button>
            </Link>
          </>
        )}

      </Card>
    </div>
  );
}
